shared_html.shared_css:
/* ============================================================
   Shared nav + footer — Atelier Lucius Vennius
   ============================================================ */

:root {
  --rule: 1px solid var(--primary);
  --frieze-h: 28px;
}

/* ---------- HEADER ---------- */

.site-nav {
  background: var(--bg);
  color: var(--text);
  border-bottom: var(--rule);
  font-family: 'Inter', system-ui, sans-serif;
}

.site-nav__inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 2.25rem 2rem 1.25rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.site-nav__wordmark {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-decoration: none;
  color: var(--primary);
  gap: 0.35rem;
}

.site-nav__kicker {
  font-family: 'Inter', sans-serif;
  font-size: 0.7rem;
  letter-spacing: 0.35em;
  text-transform: uppercase;
  color: var(--accent);
}

.site-nav__name {
  font-family: 'Marcellus', serif;
  font-size: clamp(1.6rem, 3.2vw, 2.4rem);
  letter-spacing: 0.18em;
  text-transform: uppercase;
  line-height: 1;
}

.site-nav__sub {
  font-family: 'Marcellus', serif;
  font-size: 0.78rem;
  letter-spacing: 0.4em;
  text-transform: uppercase;
  color: var(--text-emphasis);
}

/* Meander frieze — animated band (the one looped animation) */
.site-nav__meander {
  width: 100%;
  height: var(--frieze-h);
  margin: 1.25rem 0 1rem;
  border-top: var(--rule);
  border-bottom: var(--rule);
  overflow: hidden;
  position: relative;
}

.site-nav__meander-track,
.site-footer__frieze-track {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(to right,
      var(--primary) 0, var(--primary) 2px, transparent 2px, transparent 8px,
      var(--primary) 8px, var(--primary) 10px, transparent 10px, transparent 16px,
      var(--primary) 16px, var(--primary) 18px, transparent 18px, transparent 32px),
    linear-gradient(to bottom,
      transparent 0, transparent 6px,
      var(--primary) 6px, var(--primary) 8px,
      transparent 8px, transparent 20px,
      var(--primary) 20px, var(--primary) 22px,
      transparent 22px);
  background-size: 32px 100%, 100% 28px;
  background-repeat: repeat-x, repeat-x;
  animation: meander-glide 12s linear infinite;
}

@keyframes meander-glide {
  from { background-position: 0 0, 0 0; }
  to   { background-position: 320px 0, 0 0; }
}

/* Nav links */
.site-nav__links ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 2.25rem;
}

.site-nav__links a {
  font-family: 'Marcellus', serif;
  font-size: 0.95rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  text-decoration: none;
  color: var(--primary);
  padding: 0.25rem 0;
  border-bottom: 1px solid transparent;
  transition: color .2s ease, border-color .2s ease;
}

.site-nav__links a:hover,
.site-nav__links a:focus {
  color: var(--accent);
  border-bottom-color: var(--secondary);
}

/* ---------- FOOTER ---------- */

.site-footer {
  background: var(--bg);
  color: var(--text);
  border-top: var(--rule);
  margin-top: 4rem;
  font-family: 'Inter', sans-serif;
}

.site-footer__frieze {
  width: 100%;
  height: var(--frieze-h);
  border-bottom: var(--rule);
  overflow: hidden;
  position: relative;
}

/* Footer frieze is static — animation lives only in the header to keep
   exactly one animated ornament on the page. */
.site-footer__frieze-track {
  animation: none;
}

.site-footer__inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 3rem 2rem 1.5rem;
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 2.5rem;
  align-items: start;
}

.site-footer__col {
  font-size: 0.9rem;
  line-height: 1.7;
  color: var(--text);
}

.site-footer__col p {
  margin: 0;
}

.site-footer__col--center {
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.85rem;
}

.site-footer__heading {
  font-family: 'Marcellus', serif;
  font-size: 0.78rem;
  letter-spacing: 0.32em;
  text-transform: uppercase;
  color: var(--accent);
  margin: 0 0 0.6rem;
  font-weight: 400;
}

.site-footer__seal {
  width: 76px;
  height: 76px;
  border: 2px solid var(--primary);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.site-footer__seal::before,
.site-footer__seal::after {
  content: "";
  position: absolute;
  inset: 4px;
  border: 1px solid var(--secondary);
  border-radius: 50%;
}

.site-footer__seal::after {
  inset: 8px;
  border-color: var(--primary);
}

.site-footer__seal-mark {
  font-family: 'Marcellus', serif;
  font-size: 1.05rem;
  letter-spacing: 0.15em;
  color: var(--primary);
  z-index: 1;
}

.site-footer__motto {
  font-family: 'Marcellus', serif;
  font-size: 0.78rem;
  letter-spacing: 0.34em;
  text-transform: uppercase;
  color: var(--text-emphasis);
}

.site-footer__nav {
  border-top: var(--rule);
  margin-top: 1rem;
}

.site-footer__nav ul {
  list-style: none;
  margin: 0;
  padding: 1.25rem 2rem;
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 1.75rem;
}

.site-footer__nav a {
  font-family: 'Marcellus', serif;
  font-size: 0.78rem;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  text-decoration: none;
  color: var(--primary);
}

.site-footer__nav a:hover {
  color: var(--accent);
}

.site-footer__colophon {
  text-align: center;
  font-size: 0.72rem;
  letter-spacing: 0.12em;
  color: var(--primary);
  opacity: 0.7;
  padding: 0.75rem 2rem 2rem;
  margin: 0;
  font-style: italic;
}

/* ---------- Responsive ---------- */

@media (max-width: 720px) {
  .site-nav__links ul { gap: 1.1rem; }
  .site-nav__links a { font-size: 0.82rem; letter-spacing: 0.18em; }
  .site-footer__inner {
    grid-template-columns: 1fr;
    text-align: center;
  }
  .site-footer__col--center { order: -1; }
}

@media (prefers-reduced-motion: reduce) {
  .site-nav__meander-track { animation: none; }
}
